-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(materialized='table') }}

with
quarantined as (
    select
        cartivo_record_id,
        cartivo_order_id,
        cartivo_product_id,
        line_number,
        quantity,
        unit_price,
        line_revenue,
        currency,
        order_date,
        violation_00,
        violation_01
    from {{ ref("ecommerce__cartivo_order_line_extract__checked") }}
),
violations as (
    select
        'cartivo_record_id_not_null' as rule_name,
        cartivo_record_id,
        cartivo_order_id,
        cartivo_product_id,
        line_number,
        quantity,
        unit_price,
        line_revenue,
        currency,
        order_date
    from quarantined
    where violation_00

    union all

    select
        'cartivo_record_id_unique' as rule_name,
        cartivo_record_id,
        cartivo_order_id,
        cartivo_product_id,
        line_number,
        quantity,
        unit_price,
        line_revenue,
        currency,
        order_date
    from quarantined
    where violation_01
)

select
    rule_name,
    cartivo_record_id,
    cartivo_order_id,
    cartivo_product_id,
    line_number,
    quantity,
    unit_price,
    line_revenue,
    currency,
    order_date
from violations
